}

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;margin-bottom:4px;">Normalization type</div>
<div id="normButtons" style="display:flex;flex-direction:column;gap:4px;">
  <button data-norm="BatchNorm" class="active">a) BatchNorm</button>
  <button data-norm="GhostNorm">b) GhostNorm</button>
  <button data-norm="LayerNorm">c) LayerNorm</button>
  <button data-norm="GroupNorm">d) GroupNorm</button>
  <button data-norm="InstanceNorm">e) InstanceNorm</button>
</div>
<button id="sweepToggle" class="active" style="margin-top:8px;">Pause aggregation sweep</button>
<div style="display:flex;gap:6px;margin-top:8px;">
  <button id="prevStep" style="flex:1;">◀ Step</button>
  <button id="nextStep" style="flex:1;">Step ▶</button>
</div>
<div id="stepTitle" style="font-weight:700;margin-top:8px;">BatchNorm</div>
<div id="stepNarration" style="font-size:11px;line-height:1.35;color:#333;">
  The orange slab fixes one channel and pools across all batch indices and all positions.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// activation cells → 216 BoxGeometry(0.98,0.98,0.98) meshes, translucent blue-gray excluded, opaque orange statistic, pale peach ghost group
// cell grid       → EdgesGeometry line segments on every unit cell, dark blue-gray
// outer boundary  → BoxGeometry(6,6,6) EdgesGeometry line segments, dark blue-gray
// axis arrows     → THREE.ArrowHelper for +Y position, +Z channel, +X batch index
// aggregation     → translucent thin BoxGeometry sweep sheet/bar moving through selected orange set
// selected extent → LineSegments rectangular bounding box around the statistic scope
// labels          → addLabel HTML labels for panel letter, method title, axes, pooling badges, μ, σ² marker

const N = 6;
const methods = {
  BatchNorm: {
    letter: 'a)',
    title: 'BatchNorm',
    pooled: ['position', 'batch index'],
    sweepAxis: 'x',
    narration: 'The orange slab fixes one channel and pools across all batch indices and all positions. One μ and σ² are estimated for that channel over the whole mini-batch.',
    isOrange: (i, j, k) => k === 0,
    isPeach: () => false,
  },
  GhostNorm: {
    letter: 'b)',
    title: 'GhostNorm',
    pooled: ['position', 'ghost batch'],
    sweepAxis: 'x',
    narration: 'GhostNorm keeps the BatchNorm idea but restricts the batch axis to a smaller ghost batch. The pale region shows other batch examples that are nearby but excluded from this statistic.',
    isOrange: (i, j, k) => k === 0 && i >= 2 && i <= 3,
    isPeach: (i, j, k) => k === 0 && i >= 4 && i <= 5,
  },
  LayerNorm: {
    letter: 'c)',
    title: 'LayerNorm',
    pooled: ['position', 'channel'],
    sweepAxis: 'z',
    narration: 'LayerNorm fixes one batch example and pools across all channels and all positions inside that sample. The statistic no longer depends on other examples in the batch.',
    isOrange: (i, j, k) => i === 0,
    isPeach: () => false,
  },
  GroupNorm: {
    letter: 'd)',
    title: 'GroupNorm',
    pooled: ['position', 'channel group'],
    sweepAxis: 'z',
    narration: 'GroupNorm also works within one sample, but pools only a subset of channels together with all positions. Different channel groups get separate μ and σ² values.',
    isOrange: (i, j, k) => i === 1 && k >= 0 && k <= 1,
    isPeach: () => false,
  },
  InstanceNorm: {
    letter: 'e)',
    title: 'InstanceNorm',
    pooled: ['position'],
    sweepAxis: 'y',
    narration: 'InstanceNorm fixes both the batch example and the channel, pooling only over spatial positions. The orange column is the smallest scope shown here.',
    isOrange: (i, j, k) => i === 2 && k === 2,
    isPeach: () => false,
  },
};

let activeMethod = 'BatchNorm';
let activeStep = 0;
let sweepEnabled = true;
const stepOrder = ['BatchNorm', 'GhostNorm', 'LayerNorm', 'GroupNorm', 'InstanceNorm'];

scene.add(new THREE.AmbientLight(0xffffff, 1.35));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.25);
keyLight.position.set(5, 8, 6);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.45);
fillLight.position.set(-5, 4, -4);
scene.add(fillLight);

const cubeGroup = new THREE.Group();
scene.add(cubeGroup);

const cellGeom = new THREE.BoxGeometry(0.98, 0.98, 0.98);
const edgeGeom = new THREE.EdgesGeometry(cellGeom);
const grayMat = new THREE.MeshLambertMaterial({
  color: 0xd6dee2,
  transparent: true,
  opacity: 0.36,
  depthWrite: false,
});
const orangeMat = new THREE.MeshLambertMaterial({
  color: 0xd97845,
  transparent: false,
  opacity: 1,
});
const peachMat = new THREE.MeshLambertMaterial({
  color: 0xead2c6,
  transparent: true,
  opacity: 0.74,
  depthWrite: false,
});
const lineMat = new THREE.LineBasicMaterial({ color: 0x344247, transparent: true, opacity: 0.9 });
const heavyLineMat = new THREE.LineBasicMaterial({ color: 0x263238 });
const selectLineMat = new THREE.LineBasicMaterial({ color: 0x9a4b2d });

function cellCenter(i, j, k) {
  return new THREE.Vector3(2.5 - i, j + 0.5, 2.5 - k);
}

const cells = [];
for (let i = 0; i < N; i++) {
  for (let j = 0; j < N; j++) {
    for (let k = 0; k < N; k++) {
      const mesh = new THREE.Mesh(cellGeom, grayMat);
      mesh.position.copy(cellCenter(i, j, k));
      mesh.userData.cell = { i, j, k };
      const edges = new THREE.LineSegments(edgeGeom, lineMat);
      mesh.add(edges);
      cubeGroup.add(mesh);
      cells.push(mesh);
      registerInteractive(mesh, {
        tooltip: 'Click to inspect this activation cell',
        title: 'Activation cell',
        body: 'Orange cells share one mean μ and variance σ². Gray cells are excluded from the selected statistic.',
        onClick: (_hit, object) => {
          const c = object.userData.cell;
          const method = methods[activeMethod];
          if (method.isOrange(c.i, c.j, c.k)) {
            showPopup(
              `${method.title}: selected statistic scope`,
              `${method.narration}<br><br>This orange cell is one of the activations contributing to the displayed μ and σ².`
            );
          } else if (method.isPeach(c.i, c.j, c.k)) {
            showPopup(
              'Neighboring ghost batch',
              'The pale peach cells are a nearby ghost-batch group. They are visible for comparison but are not included in the orange group’s μ and σ².'
            );
          } else {
            showPopup(
              'Excluded activation',
              'This gray activation is outside the selected normalization statistic for the current method.'
            );
          }
        },
      });
    }
  }
}

const outer = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(6.04, 6.04, 6.04)),
  heavyLineMat
);
outer.position.set(0, 3, 0);
scene.add(outer);

const yArrow = new THREE.ArrowHelper(
  new THREE.Vector3(0, 1, 0),
  new THREE.Vector3(-3.55, -0.15, 3.35),
  6.45,
  0x344247,
  0.22,
  0.10
);
const xArrow = new THREE.ArrowHelper(
  new THREE.Vector3(1, 0, 0),
  new THREE.Vector3(-3.25, -0.22, 3.45),
  6.35,
  0x344247,
  0.22,
  0.10
);
const zArrow = new THREE.ArrowHelper(
  new THREE.Vector3(0, 0, 1),
  new THREE.Vector3(3.25, -0.22, -3.35),
  6.35,
  0x344247,
  0.22,
  0.10
);
scene.add(yArrow, xArrow, zArrow);

const sweepMat = new THREE.MeshBasicMaterial({
  color: 0xfff176,
  transparent: true,
  opacity: 0.44,
  depthWrite: false,
  side: THREE.DoubleSide,
});
const sweepMesh = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), sweepMat);
scene.add(sweepMesh);

const selectionBox = new THREE.LineSegments(new THREE.BufferGeometry(), selectLineMat);
scene.add(selectionBox);

function selectedCellsFor(methodName) {
  const method = methods[methodName];
  const out = [];
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      for (let k = 0; k < N; k++) {
        if (method.isOrange(i, j, k)) out.push({ i, j, k, p: cellCenter(i, j, k) });
      }
    }
  }
  return out;
}

function bboxFromSelected(selected) {
  const min = new THREE.Vector3(Infinity, Infinity, Infinity);
  const max = new THREE.Vector3(-Infinity, -Infinity, -Infinity);
  for (const c of selected) {
    min.min(new THREE.Vector3(c.p.x - 0.5, c.p.y - 0.5, c.p.z - 0.5));
    max.max(new THREE.Vector3(c.p.x + 0.5, c.p.y + 0.5, c.p.z + 0.5));
  }
  return { min, max, center: min.clone().add(max).multiplyScalar(0.5), size: max.clone().sub(min) };
}

function setSelectionBox(box) {
  const { min, max } = box;
  const pts = [
    [min.x, min.y, min.z], [max.x, min.y, min.z],
    [max.x, min.y, min.z], [max.x, max.y, min.z],
    [max.x, max.y, min.z], [min.x, max.y, min.z],
    [min.x, max.y, min.z], [min.x, min.y, min.z],
    [min.x, min.y, max.z], [max.x, min.y, max.z],
    [max.x, min.y, max.z], [max.x, max.y, max.z],
    [max.x, max.y, max.z], [min.x, max.y, max.z],
    [min.x, max.y, max.z], [min.x, min.y, max.z],
    [min.x, min.y, min.z], [min.x, min.y, max.z],
    [max.x, min.y, min.z], [max.x, min.y, max.z],
    [max.x, max.y, min.z], [max.x, max.y, max.z],
    [min.x, max.y, min.z], [min.x, max.y, max.z],
  ].flat();
  selectionBox.geometry.dispose();
  selectionBox.geometry = new THREE.BufferGeometry();
  selectionBox.geometry.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
}

function applyMethod(methodName) {
  activeMethod = methodName;
  activeStep = stepOrder.indexOf(methodName);
  const method = methods[methodName];

  for (const mesh of cells) {
    const { i, j, k } = mesh.userData.cell;
    if (method.isOrange(i, j, k)) mesh.material = orangeMat;
    else if (method.isPeach(i, j, k)) mesh.material = peachMat;
    else mesh.material = grayMat;
  }

  const selected = selectedCellsFor(methodName);
  const box = bboxFromSelected(selected);
  setSelectionBox(box);

  if (panelLabel) panelLabel.div.innerHTML = method.letter;
  if (titleLabel) titleLabel.div.innerHTML = method.title;
  if (muLabel) {
    muLabel.pos.copy(box.center).add(new THREE.Vector3(0.15, 0.55, 0.15));
    muLabel.div.innerHTML = 'μ, σ²';
  }

  for (let n = 0; n < badgeLabels.length; n++) {
    if (method.pooled[n]) {
      badgeLabels[n].div.innerHTML = `pools ${method.pooled[n]}`;
      badgeLabels[n].pos.set(3.75, 5.75 - n * 0.48, 2.4);
    } else {
      badgeLabels[n].div.innerHTML = '';
    }
  }

  document.querySelectorAll('#normButtons button').forEach(btn => {
