  const { min, max } = box;
  const pts = [
    [min.x, min.y, min.z], [max.x, min.y, min.z],
    [max.x, min.y, min.z], [max.x, max.y, min.z],
    [max.x, max.y, min.z], [min.x, max.y, min.z],
    [min.x, max.y, min.z], [min.x, min.y, min.z],
    [min.x, min.y, max.z], [max.x, min.y, max.z],
    [max.x, min.y, max.z], [max.x, max.y, max.z],
    [max.x, max.y, max.z], [min.x, max.y, max.z],
    [min.x, max.y, max.z], [min.x, min.y, max.z],
    [min.x, min.y, min.z], [min.x, min.y, max.z],
    [max.x, min.y, min.z], [max.x, min.y, max.z],
    [max.x, max.y, min.z], [max.x, max.y, max.z],
    [min.x, max.y, min.z], [min.x, max.y, max.z],
  ].flat();
  selectionBox.geometry.dispose();
  selectionBox.geometry = new THREE.BufferGeometry();
  selectionBox.geometry.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
}

function applyMethod(methodName) {
  activeMethod = methodName;
  activeStep = stepOrder.indexOf(methodName);
  const method = methods[methodName];

  for (const mesh of cells) {
    const { i, j, k } = mesh.userData.cell;
    if (method.isOrange(i, j, k)) mesh.material = orangeMat;
    else if (method.isPeach(i, j, k)) mesh.material = peachMat;
    else mesh.material = grayMat;
  }

  const selected = selectedCellsFor(methodName);
  const box = bboxFromSelected(selected);
  setSelectionBox(box);

  if (panelLabel) panelLabel.div.innerHTML = method.letter;
  if (titleLabel) titleLabel.div.innerHTML = method.title;
  if (muLabel) {
    muLabel.pos.copy(box.center).add(new THREE.Vector3(0.15, 0.55, 0.15));
    muLabel.div.innerHTML = 'μ, σ²';
  }

  for (let n = 0; n < badgeLabels.length; n++) {
    if (method.pooled[n]) {
      badgeLabels[n].div.innerHTML = `pools ${method.pooled[n]}`;
      badgeLabels[n].pos.set(3.75, 5.75 - n * 0.48, 2.4);
    } else {
      badgeLabels[n].div.innerHTML = '';
    }
  }

  document.querySelectorAll('#normButtons button').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.norm === methodName);
  });
  document.getElementById('stepTitle').textContent = method.title;
  document.getElementById('stepNarration').textContent = method.narration;
}

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.68,
  target: [0, 2.75, 0],
});

const panelLabel = addLabel('a)', new THREE.Vector3(-4.15, 6.62, 3.45), {
  fontSize: '34px',
  color: '#111',
});
const titleLabel = addLabel('BatchNorm', new THREE.Vector3(0, -0.88, 0.15), {
  fontSize: '28px',
  color: '#111',
});
addLabel('<span style="display:inline-block;transform:rotate(-90deg);">Position</span>', new THREE.Vector3(-3.95, 3.1, 3.55), {
  fontSize: '24px',
  color: '#344247',
});
addLabel('<span style="display:inline-block;transform:rotate(31deg);">Channel</span>', new THREE.Vector3(2.25, -0.58, -2.7), {
  fontSize: '23px',
  color: '#344247',
});
addLabel('<span style="display:inline-block;transform:rotate(-24deg);">batch index</span>', new THREE.Vector3(1.15, -0.58, 3.55), {
  fontSize: '23px',
  color: '#344247',
});
const muLabel = addLabel('μ, σ²', new THREE.Vector3(0, 3.4, 2.9), {
  fontSize: '19px',
  bold: true,
  color: '#111',
  background: 'rgba(255,255,255,0.86)',
});
const badgeLabels = [
  addLabel('', new THREE.Vector3(3.75, 5.75, 2.4), { fontSize: '13px', color: '#111', background: 'rgba(255,241,118,0.88)' }),
  addLabel('', new THREE.Vector3(3.75, 5.25, 2.4), { fontSize: '13px', color: '#111', background: 'rgba(255,241,118,0.88)' }),
  addLabel('', new THREE.Vector3(3.75, 4.75, 2.4), { fontSize: '13px', color: '#111', background: 'rgba(255,241,118,0.88)' }),
];

applyMethod('BatchNorm');

document.getElementById('btnReset').style.display = '';
document.querySelectorAll('#normButtons button').forEach(btn => {
  btn.addEventListener('click', () => {
    applyMethod(btn.dataset.norm);
    showPopup(methods[activeMethod].title, methods[activeMethod].narration);
  });
});

document.getElementById('sweepToggle').addEventListener('click', () => {
  sweepEnabled = !sweepEnabled;
  const btn = document.getElementById('sweepToggle');
  btn.classList.toggle('active', sweepEnabled);
  btn.textContent = sweepEnabled ? 'Pause aggregation sweep' : 'Resume aggregation sweep';
  sweepMesh.visible = sweepEnabled;
});

function goToStep(step = 0) {
  if (typeof step === 'string') {
    const idx = stepOrder.indexOf(step);
    if (idx >= 0) step = idx;
  }
  activeStep = ((step % stepOrder.length) + stepOrder.length) % stepOrder.length;
  applyMethod(stepOrder[activeStep]);
  showPopup(methods[activeMethod].title, methods[activeMethod].narration);
}
window.goToStep = goToStep;

document.getElementById('prevStep').addEventListener('click', () => goToStep(activeStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(activeStep + 1));

let sweepStart = performance.now();
function updateSweep() {
  requestAnimationFrame(updateSweep);
  const method = methods[activeMethod];
  const selected = selectedCellsFor(activeMethod);
  const box = bboxFromSelected(selected);
  const t = ((performance.now() - sweepStart) * 0.00045) % 1;
  const tri = t < 0.5 ? t * 2 : 2 - t * 2;
  sweepMesh.visible = sweepEnabled;

  if (!sweepEnabled) return;

  const center = box.center.clone();
  const pad = 0.08;
  if (method.sweepAxis === 'x') {
    center.x = box.min.x + tri * (box.max.x - box.min.x);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(0.08, box.size.y + pad, box.size.z + pad);
  } else if (method.sweepAxis === 'z') {
    center.z = box.min.z + tri * (box.max.z - box.min.z);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(box.size.x + pad, box.size.y + pad, 0.08);
  } else {
    center.y = box.min.y + tri * (box.max.y - box.min.y);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(box.size.x + pad, 0.08, box.size.z + pad);
  }
}
updateSweep();
// @FIGURE_CODE_END

