}

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;margin-bottom:4px;">Normalization type</div>
<div id="normalizationType" style="display:flex;flex-direction:column;gap:4px;">
  <button data-norm="BatchNorm" class="active">a) BatchNorm</button>
  <button data-norm="GhostNorm">b) GhostNorm</button>
  <button data-norm="LayerNorm">c) LayerNorm</button>
  <button data-norm="GroupNorm">d) GroupNorm</button>
  <button data-norm="InstanceNorm">e) InstanceNorm</button>
</div>
<button id="allPanelsToggle" class="active" style="margin-top:8px;">Show selected panel only</button>
<button id="overlayToggle" style="margin-top:4px;">Show μ/σ² and pooled axes</button>
<button id="aggregationSweep" style="margin-top:4px;">Show aggregation sweep</button>
<div style="display:flex;gap:6px;margin-top:8px;">
  <button id="prevStep" style="flex:1;">◀ Step</button>
  <button id="nextStep" style="flex:1;">Step ▶</button>
</div>
<div id="stepTitle" style="font-weight:700;margin-top:8px;">BatchNorm</div>
<div id="stepNarration" style="font-size:11px;line-height:1.35;color:#333;">
  The orange slab fixes one channel and pools across all batch indices and all positions.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// activation cells     → five 6×6×6 arrays of opaque BoxGeometry(0.98) meshes: gray excluded, orange selected, pale peach GhostNorm neighbor
// cell lattice         → EdgesGeometry line segments attached to every unit cell, dark blue-gray and hidden by opaque cell faces
// outer cube boundary  → LineSegments EdgesGeometry(BoxGeometry(6.04,6.04,6.04)) for each panel
// axis direction marks → small ArrowHelper objects for +Y position, +Z channel, and +X batch index on each cube
// optional sweep       → translucent amber BoxGeometry sheet/bar, normally hidden, animated only through selected orange extent
// optional markers     → addLabel labels for μ, σ² and pooled-axis badges, normally hidden for source-faithful view
// figure text          → addLabel panel letters a–e, method titles, and three axis labels for every visible panel

const N = 6;
const methodOrder = ['BatchNorm', 'GhostNorm', 'LayerNorm', 'GroupNorm', 'InstanceNorm'];

const methods = {
  BatchNorm: {
    letter: 'a)',
    title: 'BatchNorm',
    pooled: ['position', 'batch index'],
    sweepAxis: 'x',
    narration: 'The orange slab fixes one channel and pools across all batch indices and all positions. One μ and σ² are estimated for that channel over the whole mini-batch.',
    isOrange: (i, j, k) => k === 0,
    isPeach: () => false,
  },
  GhostNorm: {
    letter: 'b)',
    title: 'GhostNorm',
    pooled: ['position', 'ghost batch'],
    sweepAxis: 'x',
    narration: 'GhostNorm keeps the BatchNorm idea but restricts the batch axis to a smaller ghost batch. The pale region shows other batch examples that are nearby but excluded from this statistic.',
    isOrange: (i, j, k) => k === 0 && i >= 2 && i <= 3,
    isPeach: (i, j, k) => k === 0 && i >= 4 && i <= 5,
  },
  LayerNorm: {
    letter: 'c)',
    title: 'LayerNorm',
    pooled: ['position', 'channel'],
    sweepAxis: 'z',
    narration: 'LayerNorm fixes one batch example and pools across all channels and all positions inside that sample. The statistic no longer depends on other examples in the batch.',
    isOrange: (i, j, k) => i === 0,
    isPeach: () => false,
  },
  GroupNorm: {
    letter: 'd)',
    title: 'GroupNorm',
    pooled: ['position', 'channel group'],
    sweepAxis: 'z',
    narration: 'GroupNorm also works within one sample, but pools only a subset of channels together with all positions. Different channel groups get separate μ and σ² values.',
    isOrange: (i, j, k) => i === 1 && k >= 0 && k <= 1,
    isPeach: () => false,
  },
  InstanceNorm: {
    letter: 'e)',
    title: 'InstanceNorm',
    pooled: ['position'],
    sweepAxis: 'y',
    narration: 'InstanceNorm fixes both the batch example and the channel, pooling only over spatial positions. The orange column is the smallest scope shown here.',
    isOrange: (i, j, k) => i === 2 && k === 2,
    isPeach: () => false,
  },
};

let activeMethod = 'BatchNorm';
let activeStep = 0;
let showAllPanels = true;
let showTeachingOverlays = false;
let sweepEnabled = false;

scene.add(new THREE.AmbientLight(0xffffff, 1.9));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.15);
keyLight.position.set(6, 9, 7);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.55);
fillLight.position.set(-6, 5, -5);
scene.add(fillLight);

const cellGeom = new THREE.BoxGeometry(0.98, 0.98, 0.98);
const edgeGeom = new THREE.EdgesGeometry(cellGeom);

const grayMat = new THREE.MeshLambertMaterial({ color: 0xd6dee2, transparent: false, opacity: 1, depthWrite: true });
const orangeMat = new THREE.MeshLambertMaterial({ color: 0xd97845, transparent: false, opacity: 1, depthWrite: true });
const peachMat = new THREE.MeshLambertMaterial({ color: 0xead2c6, transparent: false, opacity: 0.98, depthWrite: true });
const lineMat = new THREE.LineBasicMaterial({ color: 0x344247, transparent: true, opacity: 0.95 });
const outerLineMat = new THREE.LineBasicMaterial({ color: 0x344247, transparent: true, opacity: 1 });

const sweepMat = new THREE.MeshBasicMaterial({
  color: 0xffd54f,
  transparent: true,
  opacity: 0.34,
  depthWrite: false,
  side: THREE.DoubleSide,
});
const sweepMesh = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), sweepMat);
sweepMesh.visible = false;

function cellCenter(i, j, k) {
  return new THREE.Vector3(2.5 - i, j + 0.5, 2.5 - k);
}

function selectedCellsFor(methodName) {
  const method = methods[methodName];
  const out = [];
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      for (let k = 0; k < N; k++) {
        if (method.isOrange(i, j, k)) out.push({ i, j, k, p: cellCenter(i, j, k) });
      }
    }
  }
  return out;
}

function bboxFromSelected(selected) {
  const min = new THREE.Vector3(Infinity, Infinity, Infinity);
  const max = new THREE.Vector3(-Infinity, -Infinity, -Infinity);
  for (const c of selected) {
    min.min(new THREE.Vector3(c.p.x - 0.5, c.p.y - 0.5, c.p.z - 0.5));
    max.max(new THREE.Vector3(c.p.x + 0.5, c.p.y + 0.5, c.p.z + 0.5));
  }
  return { min, max, center: min.clone().add(max).multiplyScalar(0.5), size: max.clone().sub(min) };
}

const panels = {};
const screenRight = new THREE.Vector3(1, 0, -1).normalize();

function makePanel(methodName) {
  const method = methods[methodName];
  const group = new THREE.Group();
  group.userData.methodName = methodName;
  scene.add(group);

  const cells = [];
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      for (let k = 0; k < N; k++) {
        let mat = grayMat;
        let kind = 'excluded';
        if (method.isOrange(i, j, k)) {
          mat = orangeMat;
          kind = 'orange';
        } else if (method.isPeach(i, j, k)) {
          mat = peachMat;
          kind = 'peach';
        }

        const mesh = new THREE.Mesh(cellGeom, mat);
        mesh.position.copy(cellCenter(i, j, k));
        mesh.userData.cell = { i, j, k, methodName, kind };
        const edges = new THREE.LineSegments(edgeGeom, lineMat);
        mesh.add(edges);
        group.add(mesh);
        cells.push(mesh);

        registerInteractive(mesh, {
          tooltip: kind === 'orange' ? `${method.title}: cells sharing one μ and σ²` : `${method.title}: activation cell`,
          title: method.title,
          body: kind === 'orange'
            ? `${method.narration}<br><br>Clicking an orange region focuses this normalization scope.`
            : kind === 'peach'
              ? 'This pale peach region is a neighboring ghost-batch group: visible for comparison, but excluded from the orange group’s statistic.'
              : 'Gray cells are outside the selected statistic for this normalization method.',
          onClick: () => {
            setActiveMethod(methodName, true);
            if (kind === 'orange') {
              setAllPanels(false);
              showPopup(method.title, method.narration);
            }
          },
        });
      }
    }
  }

  const outer = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.BoxGeometry(6.04, 6.04, 6.04)),
    outerLineMat
  );
  outer.position.set(0, 3, 0);
  group.add(outer);

  const yArrow = new THREE.ArrowHelper(
    new THREE.Vector3(0, 1, 0),
    new THREE.Vector3(-3.48, -0.18, 3.28),
    6.35,
    0x344247,
    0.18,
    0.075
  );
  const xArrow = new THREE.ArrowHelper(
    new THREE.Vector3(1, 0, 0),
    new THREE.Vector3(-3.08, -0.20, 3.36),
    6.15,
    0x344247,
    0.18,
    0.075
  );
  const zArrow = new THREE.ArrowHelper(
    new THREE.Vector3(0, 0, 1),
    new THREE.Vector3(3.08, -0.20, -3.18),
    6.15,
    0x344247,
    0.18,
    0.075
  );
  group.add(yArrow, xArrow, zArrow);

  panels[methodName] = {
    methodName,
    method,
    group,
    cells,
    labels: {},
  };
  return panels[methodName];
}

for (const name of methodOrder) makePanel(name);

function panelWorld(panel, local) {
  return panel.group.localToWorld(local.clone());
}

function setLabelVisibility(entry, visible) {
  if (entry?.div) entry.div.style.visibility = visible ? 'visible' : 'hidden';
}

function updatePanelLabels() {
  for (const name of methodOrder) {
    const panel = panels[name];
    if (!panel.labels.letter) continue;
    const visible = panel.group.visible;
    const small = showAllPanels;
    const fsLetter = small ? '25px' : '34px';
    const fsTitle = small ? '21px' : '30px';
    const fsAxis = small ? '18px' : '24px';

    panel.labels.letter.pos.copy(panelWorld(panel, new THREE.Vector3(-4.15, 6.70, 3.55)));
    panel.labels.title.pos.copy(panelWorld(panel, new THREE.Vector3(0, -0.98, 0.15)));
    panel.labels.position.pos.copy(panelWorld(panel, new THREE.Vector3(-3.90, 3.2, 3.46)));
    panel.labels.channel.pos.copy(panelWorld(panel, new THREE.Vector3(-2.05, -0.56, 3.35)));
    panel.labels.batch.pos.copy(panelWorld(panel, new THREE.Vector3(2.15, -0.56, 3.48)));

    panel.labels.letter.div.style.fontSize = fsLetter;
    panel.labels.title.div.style.fontSize = fsTitle;
    panel.labels.position.div.style.fontSize = fsAxis;
    panel.labels.channel.div.style.fontSize = fsAxis;
    panel.labels.batch.div.style.fontSize = fsAxis;

    for (const key of Object.keys(panel.labels)) setLabelVisibility(panel.labels[key], visible);
  }
  updateTeachingLabels();
}

function activePanel() {
  return panels[activeMethod];
}

function updateTeachingLabels() {
  const panel = activePanel();
  const method = methods[activeMethod];
  const selected = selectedCellsFor(activeMethod);
  const box = bboxFromSelected(selected);
  const show = showTeachingOverlays && panel.group.visible;

  const muWorld = panelWorld(panel, box.center.clone().add(new THREE.Vector3(0.14, 0.54, 0.14)));
  muLabel.pos.copy(muWorld);
  muLabel.div.innerHTML = 'μ, σ²';
  setLabelVisibility(muLabel, show);

  for (let n = 0; n < badgeLabels.length; n++) {
    const badge = badgeLabels[n];
    if (show && method.pooled[n]) {
      badge.div.innerHTML = `pools ${method.pooled[n]}`;
      badge.pos.copy(panelWorld(panel, new THREE.Vector3(3.85, 5.82 - n * 0.48, 2.35)));
      setLabelVisibility(badge, true);
    } else {
      badge.div.innerHTML = '';
      setLabelVisibility(badge, false);
    }
  }
}

function updateLayout(refit = true) {
  const allScale = 0.47;
  const focusScale = 0.92;
  const gap = 6.85;

  for (let idx = 0; idx < methodOrder.length; idx++) {
    const name = methodOrder[idx];
    const panel = panels[name];

    if (showAllPanels) {
      panel.group.visible = true;
      panel.group.scale.setScalar(allScale);
      panel.group.position.copy(screenRight.clone().multiplyScalar((idx - 2) * gap));
    } else {
      panel.group.visible = name === activeMethod;
