        const edges = new THREE.LineSegments(edgeGeom, lineMat);
        mesh.add(edges);
        group.add(mesh);
        cells.push(mesh);

        registerInteractive(mesh, {
          tooltip: kind === 'orange' ? `${method.title}: cells sharing one μ and σ²` : `${method.title}: activation cell`,
          title: method.title,
          body: kind === 'orange'
            ? `${method.narration}<br><br>Clicking an orange region focuses this normalization scope.`
            : kind === 'peach'
              ? 'This pale peach region is a neighboring ghost-batch group: visible for comparison, but excluded from the orange group’s statistic.'
              : 'Gray cells are outside the selected statistic for this normalization method.',
          onClick: () => {
            setActiveMethod(methodName, true);
            if (kind === 'orange') {
              setAllPanels(false);
              showPopup(method.title, method.narration);
            }
          },
        });
      }
    }
  }

  const outer = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.BoxGeometry(6.04, 6.04, 6.04)),
    outerLineMat
  );
  outer.position.set(0, 3, 0);
  group.add(outer);

  const yArrow = new THREE.ArrowHelper(
    new THREE.Vector3(0, 1, 0),
    new THREE.Vector3(-3.48, -0.18, 3.28),
    6.35,
    0x344247,
    0.18,
    0.075
  );
  const xArrow = new THREE.ArrowHelper(
    new THREE.Vector3(1, 0, 0),
    new THREE.Vector3(-3.08, -0.20, 3.36),
    6.15,
    0x344247,
    0.18,
    0.075
  );
  const zArrow = new THREE.ArrowHelper(
    new THREE.Vector3(0, 0, 1),
    new THREE.Vector3(3.08, -0.20, -3.18),
    6.15,
    0x344247,
    0.18,
    0.075
  );
  group.add(yArrow, xArrow, zArrow);

  panels[methodName] = {
    methodName,
    method,
    group,
    cells,
    labels: {},
  };
  return panels[methodName];
}

for (const name of methodOrder) makePanel(name);

function panelWorld(panel, local) {
  return panel.group.localToWorld(local.clone());
}

function setLabelVisibility(entry, visible) {
  if (entry?.div) entry.div.style.visibility = visible ? 'visible' : 'hidden';
}

function updatePanelLabels() {
  for (const name of methodOrder) {
    const panel = panels[name];
    if (!panel.labels.letter) continue;
    const visible = panel.group.visible;
    const small = showAllPanels;
    const fsLetter = small ? '25px' : '34px';
    const fsTitle = small ? '21px' : '30px';
    const fsAxis = small ? '18px' : '24px';

    panel.labels.letter.pos.copy(panelWorld(panel, new THREE.Vector3(-4.15, 6.70, 3.55)));
    panel.labels.title.pos.copy(panelWorld(panel, new THREE.Vector3(0, -0.98, 0.15)));
    panel.labels.position.pos.copy(panelWorld(panel, new THREE.Vector3(-3.90, 3.2, 3.46)));
    panel.labels.channel.pos.copy(panelWorld(panel, new THREE.Vector3(-2.05, -0.56, 3.35)));
    panel.labels.batch.pos.copy(panelWorld(panel, new THREE.Vector3(2.15, -0.56, 3.48)));

    panel.labels.letter.div.style.fontSize = fsLetter;
    panel.labels.title.div.style.fontSize = fsTitle;
    panel.labels.position.div.style.fontSize = fsAxis;
    panel.labels.channel.div.style.fontSize = fsAxis;
    panel.labels.batch.div.style.fontSize = fsAxis;

    for (const key of Object.keys(panel.labels)) setLabelVisibility(panel.labels[key], visible);
  }
  updateTeachingLabels();
}

function activePanel() {
  return panels[activeMethod];
}

function updateTeachingLabels() {
  const panel = activePanel();
  const method = methods[activeMethod];
  const selected = selectedCellsFor(activeMethod);
  const box = bboxFromSelected(selected);
  const show = showTeachingOverlays && panel.group.visible;

  const muWorld = panelWorld(panel, box.center.clone().add(new THREE.Vector3(0.14, 0.54, 0.14)));
  muLabel.pos.copy(muWorld);
  muLabel.div.innerHTML = 'μ, σ²';
  setLabelVisibility(muLabel, show);

  for (let n = 0; n < badgeLabels.length; n++) {
    const badge = badgeLabels[n];
    if (show && method.pooled[n]) {
      badge.div.innerHTML = `pools ${method.pooled[n]}`;
      badge.pos.copy(panelWorld(panel, new THREE.Vector3(3.85, 5.82 - n * 0.48, 2.35)));
      setLabelVisibility(badge, true);
    } else {
      badge.div.innerHTML = '';
      setLabelVisibility(badge, false);
    }
  }
}

function updateLayout(refit = true) {
  const allScale = 0.47;
  const focusScale = 0.92;
  const gap = 6.85;

  for (let idx = 0; idx < methodOrder.length; idx++) {
    const name = methodOrder[idx];
    const panel = panels[name];

    if (showAllPanels) {
      panel.group.visible = true;
      panel.group.scale.setScalar(allScale);
      panel.group.position.copy(screenRight.clone().multiplyScalar((idx - 2) * gap));
    } else {
      panel.group.visible = name === activeMethod;
      panel.group.scale.setScalar(focusScale);
      panel.group.position.set(0, 0, 0);
    }
  }

  const panel = activePanel();
  if (sweepMesh.parent !== panel.group) panel.group.add(sweepMesh);
  updatePanelLabels();
  updateSweep(true);

  if (refit) {
    setCameraView({
      projection: 'orthographic',
      axisScreenAngles: { x: 30, z: 30 },
      rollDeg: 0,
      heightFraction: showAllPanels ? 0.78 : 0.68,
    });
  }
}

updateLayout(false);

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.78,
});

for (const name of methodOrder) {
  const panel = panels[name];
  panel.labels.letter = addLabel(panel.method.letter, new THREE.Vector3(), { fontSize: '25px', color: '#111' });
  panel.labels.title = addLabel(panel.method.title, new THREE.Vector3(), { fontSize: '21px', color: '#111' });
  panel.labels.position = addLabel('<span style="display:inline-block;transform:rotate(-90deg);">Position</span>', new THREE.Vector3(), { fontSize: '18px', color: '#344247' });
  panel.labels.channel = addLabel('<span style="display:inline-block;transform:rotate(31deg);">Channel</span>', new THREE.Vector3(), { fontSize: '18px', color: '#344247' });
  panel.labels.batch = addLabel('<span style="display:inline-block;transform:rotate(-24deg);">batch index</span>', new THREE.Vector3(), { fontSize: '18px', color: '#344247' });
}

const muLabel = addLabel('', new THREE.Vector3(), {
  fontSize: '18px',
  bold: true,
  color: '#111',
  background: 'rgba(255,255,255,0.9)',
});
const badgeLabels = [
  addLabel('', new THREE.Vector3(), { fontSize: '12px', color: '#111', background: 'rgba(255,245,157,0.9)' }),
  addLabel('', new THREE.Vector3(), { fontSize: '12px', color: '#111', background: 'rgba(255,245,157,0.9)' }),
  addLabel('', new THREE.Vector3(), { fontSize: '12px', color: '#111', background: 'rgba(255,245,157,0.9)' }),
];

updateLayout(true);

function setActiveMethod(methodName, updateButtons = true) {
  activeMethod = methodName;
  activeStep = methodOrder.indexOf(methodName);
  const method = methods[methodName];

  if (updateButtons) {
    document.querySelectorAll('#normalizationType button').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.norm === methodName);
    });
  }

  document.getElementById('stepTitle').textContent = method.title;
  document.getElementById('stepNarration').textContent = method.narration;
  updateLayout(true);
}

function setAllPanels(on) {
  showAllPanels = on;
  const btn = document.getElementById('allPanelsToggle');
  btn.classList.toggle('active', showAllPanels);
  btn.textContent = showAllPanels ? 'Show selected panel only' : 'Show all five panels';
  updateLayout(true);
}

document.getElementById('btnReset').style.display = '';

document.querySelectorAll('#normalizationType button').forEach(btn => {
  btn.addEventListener('click', () => {
    setActiveMethod(btn.dataset.norm, true);
    showPopup(methods[activeMethod].title, methods[activeMethod].narration);
  });
});

document.getElementById('allPanelsToggle').addEventListener('click', () => {
  setAllPanels(!showAllPanels);
});

document.getElementById('overlayToggle').addEventListener('click', () => {
  showTeachingOverlays = !showTeachingOverlays;
  const btn = document.getElementById('overlayToggle');
  btn.classList.toggle('active', showTeachingOverlays);
  btn.textContent = showTeachingOverlays ? 'Hide μ/σ² and pooled axes' : 'Show μ/σ² and pooled axes';
  updateTeachingLabels();
});

document.getElementById('aggregationSweep').addEventListener('click', () => {
  sweepEnabled = !sweepEnabled;
  const btn = document.getElementById('aggregationSweep');
  btn.classList.toggle('active', sweepEnabled);
  btn.textContent = sweepEnabled ? 'Hide aggregation sweep' : 'Show aggregation sweep';
  updateSweep(true);
});

function goToStep(step = 0) {
  if (typeof step === 'string') {
    const idx = methodOrder.indexOf(step);
    if (idx >= 0) step = idx;
  }
  activeStep = ((step % methodOrder.length) + methodOrder.length) % methodOrder.length;
  setActiveMethod(methodOrder[activeStep], true);
  showPopup(methods[activeMethod].title, methods[activeMethod].narration);
}
window.goToStep = goToStep;

document.getElementById('prevStep').addEventListener('click', () => goToStep(activeStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(activeStep + 1));

let sweepStart = performance.now();

function updateSweep(once = false) {
  const panel = activePanel();
  const method = methods[activeMethod];
  const selected = selectedCellsFor(activeMethod);
  const box = bboxFromSelected(selected);
  const t = ((performance.now() - sweepStart) * 0.00045) % 1;
  const tri = t < 0.5 ? t * 2 : 2 - t * 2;
  const pad = 0.08;

  sweepMesh.visible = sweepEnabled && panel.group.visible;
  if (sweepMesh.parent !== panel.group) panel.group.add(sweepMesh);

  const center = box.center.clone();
  if (method.sweepAxis === 'x') {
    center.x = box.min.x + tri * (box.max.x - box.min.x);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(0.075, box.size.y + pad, box.size.z + pad);
  } else if (method.sweepAxis === 'z') {
    center.z = box.min.z + tri * (box.max.z - box.min.z);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(box.size.x + pad, box.size.y + pad, 0.075);
  } else {
    center.y = box.min.y + tri * (box.max.y - box.min.y);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(box.size.x + pad, 0.075, box.size.z + pad);
  }

  if (!once) requestAnimationFrame(() => updateSweep(false));
}
updateSweep(false);
// @FIGURE_CODE_END

