// @FIGURE_CODE_BEGIN
// activation cells          → one 6×6×6 array of BoxGeometry(0.98) meshes: translucent light blue-gray excluded cells, opaque orange selected cells, pale peach GhostNorm neighbor cells
// source-face grid lattice  → LineSegments on cube faces with dark blue-gray grid lines matching the textbook cell subdivision
// selected-cell grid        → EdgesGeometry line segments attached to orange/peach cells so highlighted cubical cells remain legible
// outer cube boundary       → LineSegments EdgesGeometry(BoxGeometry(6.04,6.04,6.04)) dark blue-gray
// axis direction arrows     → three ArrowHelper objects aligned to +Y position, +Z channel, and +X batch-index axes
// aggregation sweep         → translucent amber BoxGeometry sheet/bar moving only through selected orange cells
// figure text labels        → addLabel panel letter, method title, Position, Channel, batch index, μ/σ² marker, and pooled-axis badges

const N = 6;
const methodOrder = ['BatchNorm', 'GhostNorm', 'LayerNorm', 'GroupNorm', 'InstanceNorm'];

const methods = {
  BatchNorm: {
    letter: 'a)',
    title: 'BatchNorm',
    pooled: ['position', 'batch index'],
    sweepAxis: 'x',
    narration: 'The orange slab fixes one channel and pools across all batch indices and all positions. One μ and σ² are estimated for that channel over the whole mini-batch.',
    isOrange: (i, j, k) => k === 0,
    isPeach: () => false,
    count: 36,
  },
  GhostNorm: {
    letter: 'b)',
    title: 'GhostNorm',
    pooled: ['position', 'ghost batch'],
    sweepAxis: 'x',
    narration: 'GhostNorm keeps the BatchNorm idea but restricts the batch axis to a smaller ghost batch. The pale region shows other batch examples that are nearby but excluded from this statistic.',
    isOrange: (i, j, k) => k === 0 && i >= 2 && i <= 3,
    isPeach: (i, j, k) => k === 0 && i >= 4 && i <= 5,
    count: 12,
  },
  LayerNorm: {
    letter: 'c)',
    title: 'LayerNorm',
    pooled: ['position', 'channel'],
    sweepAxis: 'z',
    narration: 'LayerNorm fixes one batch example and pools across all channels and all positions inside that sample. The statistic no longer depends on other examples in the batch.',
    isOrange: (i, j, k) => i === 0,
    isPeach: () => false,
    count: 36,
  },
  GroupNorm: {
    letter: 'd)',
    title: 'GroupNorm',
    pooled: ['position', 'channel group'],
    sweepAxis: 'z',
    narration: 'GroupNorm also works within one sample, but pools only a subset of channels together with all positions. Different channel groups get separate μ and σ² values.',
    isOrange: (i, j, k) => i === 1 && k >= 0 && k <= 1,
    isPeach: () => false,
    count: 12,
  },
  InstanceNorm: {
    letter: 'e)',
    title: 'InstanceNorm',
    pooled: ['position'],
    sweepAxis: 'y',
    narration: 'InstanceNorm fixes both the batch example and the channel, pooling only over spatial positions. The orange column is the smallest scope shown here.',
    isOrange: (i, j, k) => i === 2 && k === 2,
    isPeach: () => false,
    count: 6,
  },
};

let activeMethod = 'BatchNorm';
let activeStep = 0;
let sweepEnabled = true;
let showTeachingOverlays = true;

scene.add(new THREE.AmbientLight(0xffffff, 1.55));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.25);
keyLight.position.set(7, 10, 8);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.7);
fillLight.position.set(-6, 4, -5);
scene.add(fillLight);

const cubeGroup = new THREE.Group();
cubeGroup.position.set(0, -0.05, 0);
scene.add(cubeGroup);

const cellGeom = new THREE.BoxGeometry(0.98, 0.98, 0.98);
const selectedEdgeGeom = new THREE.EdgesGeometry(cellGeom);

const grayMat = new THREE.MeshLambertMaterial({
  color: 0xd6dee2,
  transparent: true,
  opacity: 0.86,
  depthWrite: false,
});
const orangeMat = new THREE.MeshLambertMaterial({
  color: 0xd97845,
  transparent: false,
  opacity: 1,
});
const peachMat = new THREE.MeshLambertMaterial({
  color: 0xead2c6,
  transparent: true,
  opacity: 0.98,
  depthWrite: false,
});
const selectedLineMat = new THREE.LineBasicMaterial({ color: 0x344247, transparent: true, opacity: 0.95 });
const faceGridMat = new THREE.LineBasicMaterial({ color: 0x344247, transparent: true, opacity: 0.92 });
const outerLineMat = new THREE.LineBasicMaterial({ color: 0x344247, transparent: true, opacity: 1 });

const cells = [];

function cellCenter(i, j, k) {
  return new THREE.Vector3(2.5 - i, j + 0.5, 2.5 - k);
}

function selectedCellsFor(methodName) {
  const method = methods[methodName];
  const out = [];
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      for (let k = 0; k < N; k++) {
        if (method.isOrange(i, j, k)) out.push({ i, j, k, p: cellCenter(i, j, k) });
      }
    }
  }
  return out;
}

function bboxFromSelected(selected) {
  const min = new THREE.Vector3(Infinity, Infinity, Infinity);
  const max = new THREE.Vector3(-Infinity, -Infinity, -Infinity);
  for (const c of selected) {
    min.min(new THREE.Vector3(c.p.x - 0.5, c.p.y - 0.5, c.p.z - 0.5));
    max.max(new THREE.Vector3(c.p.x + 0.5, c.p.y + 0.5, c.p.z + 0.5));
  }
  return { min, max, center: min.clone().add(max).multiplyScalar(0.5), size: max.clone().sub(min) };
}

function makeFaceGridGeometry() {
  const pts = [];
  const a = -3, b = 3;

  function addLine(x1, y1, z1, x2, y2, z2) {
    pts.push(x1, y1, z1, x2, y2, z2);
  }

  for (let t = -3; t <= 3; t++) {
    addLine(t, 6.012, a, t, 6.012, b);
    addLine(a, 6.012, t, b, 6.012, t);

    addLine(3.012, 0, t, 3.012, 6, t);
    addLine(3.012, t + 3, a, 3.012, t + 3, b);

    addLine(t, 0, 3.012, t, 6, 3.012);
    addLine(a, t + 3, 3.012, b, t + 3, 3.012);
  }

  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
  return geom;
}

for (let i = 0; i < N; i++) {
  for (let j = 0; j < N; j++) {
    for (let k = 0; k < N; k++) {
      const mesh = new THREE.Mesh(cellGeom, grayMat);
      mesh.position.copy(cellCenter(i, j, k));
      mesh.userData.cell = { i, j, k, kind: 'excluded' };

      const edge = new THREE.LineSegments(selectedEdgeGeom, selectedLineMat);
      edge.visible = false;
      mesh.add(edge);
      mesh.userData.edge = edge;

      cubeGroup.add(mesh);
      cells.push(mesh);

      registerInteractive(mesh, {
        tooltip: 'Activation cell',
        title: 'Activation cell',
        body: 'Gray cells are outside the selected normalization statistic. Orange cells share one mean μ and variance σ².',
        onClick: () => {
          const method = methods[activeMethod];
          if (mesh.userData.cell.kind === 'orange') {
            showPopup(method.title, `${method.narration}<br><br><b>${method.count}</b> highlighted cells share this one μ and σ² estimate.`);
          } else if (mesh.userData.cell.kind === 'peach') {
            showPopup('Neighboring ghost batch', 'The pale peach cells are a separate GhostNorm group shown for comparison. They are not included in the orange group’s statistic.');
          } else {
            showPopup(method.title, 'This gray activation is outside the currently highlighted statistic scope.');
          }
        },
      });
    }
  }
}

