function setLabelVisibility(entry, visible) {
  if (entry?.div) entry.div.style.visibility = visible ? 'visible' : 'hidden';
}

function worldFromCube(local) {
  return cubeGroup.localToWorld(local.clone());
}

function updateFigureLabels() {
  const method = methods[activeMethod];
  const selected = selectedCellsFor(activeMethod);
  const box = bboxFromSelected(selected);

  panelLetterLabel.div.innerHTML = method.letter;
  methodTitleLabel.div.innerHTML = method.title;

  panelLetterLabel.pos.copy(worldFromCube(new THREE.Vector3(-4.45, 6.55, 3.35)));
  methodTitleLabel.pos.copy(worldFromCube(new THREE.Vector3(0.1, -0.86, 2.62)));
  positionAxisLabel.pos.copy(worldFromCube(new THREE.Vector3(-3.82, 3.1, 3.35)));
  channelAxisLabel.pos.copy(worldFromCube(new THREE.Vector3(-2.08, -0.54, 3.42)));
  batchAxisLabel.pos.copy(worldFromCube(new THREE.Vector3(2.25, -0.54, 3.42)));

  muLabel.pos.copy(worldFromCube(box.center.clone().add(new THREE.Vector3(0.18, 0.55, 0.18))));
  setLabelVisibility(muLabel, showTeachingOverlays);

  for (let n = 0; n < badgeLabels.length; n++) {
    const badge = badgeLabels[n];
    if (showTeachingOverlays && method.pooled[n]) {
      badge.div.innerHTML = `pools ${method.pooled[n]}`;
      badge.pos.copy(worldFromCube(new THREE.Vector3(3.85, 5.78 - n * 0.52, 2.72)));
      setLabelVisibility(badge, true);
    } else {
      badge.div.innerHTML = '';
      setLabelVisibility(badge, false);
    }
  }
}

function setActiveMethod(methodName, updateButtons = true) {
  activeMethod = methodName;
  activeStep = methodOrder.indexOf(methodName);
  const method = methods[methodName];

  for (const mesh of cells) {
    const { i, j, k } = mesh.userData.cell;
    let kind = 'excluded';
    if (method.isOrange(i, j, k)) {
      kind = 'orange';
      mesh.material = orangeMat;
      mesh.renderOrder = 3;
      mesh.userData.edge.visible = true;
    } else if (method.isPeach(i, j, k)) {
      kind = 'peach';
      mesh.material = peachMat;
      mesh.renderOrder = 2;
      mesh.userData.edge.visible = true;
    } else {
      mesh.material = grayMat;
      mesh.renderOrder = 0;
      mesh.userData.edge.visible = false;
    }
    mesh.userData.cell.kind = kind;
  }

  if (updateButtons) {
    document.querySelectorAll('#normalizationType button').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.norm === methodName);
    });
  }

  document.getElementById('stepTitle').textContent = method.title;
  document.getElementById('stepNarration').textContent = method.narration;
  updateFigureLabels();
  updateSweep();
}

function focusScope() {
  const method = methods[activeMethod];
  showPopup(method.title, `${method.narration}<br><br><b>${method.count}</b> orange cells share one mean μ and one variance σ². The sweep animation stays inside exactly this selected scope.`);
}

function updateSweep() {
  const method = methods[activeMethod];
  const selected = selectedCellsFor(activeMethod);
  const box = bboxFromSelected(selected);
  const pad = 0.08;
  const t = ((performance.now() - sweepStart) * 0.00042) % 1;
  const tri = t < 0.5 ? t * 2 : 2 - t * 2;
  const center = box.center.clone();

  sweepMesh.visible = sweepEnabled;

  if (method.sweepAxis === 'x') {
    center.x = box.min.x + tri * (box.max.x - box.min.x);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(0.07, box.size.y + pad, box.size.z + pad);
  } else if (method.sweepAxis === 'z') {
    center.z = box.min.z + tri * (box.max.z - box.min.z);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(box.size.x + pad, box.size.y + pad, 0.07);
  } else {
    center.y = box.min.y + tri * (box.max.y - box.min.y);
    sweepMesh.position.copy(center);
    sweepMesh.scale.set(box.size.x + pad, 0.07, box.size.z + pad);
  }
}

function goToStep(step = 0) {
  if (typeof step === 'string') {
    const idx = methodOrder.indexOf(step);
    if (idx >= 0) step = idx;
  }
  activeStep = ((step % methodOrder.length) + methodOrder.length) % methodOrder.length;
  setActiveMethod(methodOrder[activeStep], true);
  focusScope();
}
window.goToStep = goToStep;

document.getElementById('btnReset').style.display = '';

document.querySelectorAll('#normalizationType button').forEach(btn => {
  btn.addEventListener('click', () => {
    setActiveMethod(btn.dataset.norm, true);
    focusScope();
  });
});

document.getElementById('selectScope').addEventListener('click', focusScope);

document.getElementById('aggregationSweep').addEventListener('click', () => {
  sweepEnabled = !sweepEnabled;
  const btn = document.getElementById('aggregationSweep');
  btn.classList.toggle('active', sweepEnabled);
  btn.textContent = sweepEnabled ? 'Pause aggregation sweep' : 'Animate statistic aggregation';
  updateSweep();
});

document.getElementById('overlayToggle').addEventListener('click', () => {
  showTeachingOverlays = !showTeachingOverlays;
  const btn = document.getElementById('overlayToggle');
  btn.classList.toggle('active', showTeachingOverlays);
  btn.textContent = showTeachingOverlays ? 'Hide μ/σ² and pooled axes' : 'Show μ/σ² and pooled axes';
  updateFigureLabels();
});

document.getElementById('prevStep').addEventListener('click', () => goToStep(activeStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(activeStep + 1));

let sweepStart = performance.now();
function sweepLoop() {
  updateSweep();
  requestAnimationFrame(sweepLoop);
}

